-- --------------------------------------------------------

--
-- Table structure for table `wp_posts`
--

CREATE TABLE `wp_posts` (
  `ID` bigint(20) UNSIGNED NOT NULL,
  `post_author` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `wp_posts`
--

INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(5, 3, '2018-08-29 12:16:44', '2018-08-29 12:16:44', '<label> Your Name (required)\r\n    [text* your-name] </label>\r\n\r\n<label> Your Email (required)\r\n    [email* your-email] </label>\r\n\r\n<label> Subject\r\n    [text your-subject] </label>\r\n\r\n<label> Your Message\r\n    [textarea your-message] </label>\r\n\r\n[submit \"Send\"]\n1\nKhách hàng [your-name] liên hệ\nwordpress@linhkien.maugiaodien.com\nwordpress@linhkien.maugiaodien.com\nFrom: [your-name] <[your-email]>\r\nSubject: [your-subject]\r\n\r\nMessage Body:\r\n[your-message]\n\n\n\n\n\nMẪU GIAO DIỆN WEBVN027 \"[your-subject]\"\nMẪU GIAO DIỆN WEBVN027 <wordpress@linhkien.maugiaodien.com>\n[your-email]\nMessage Body:\r\n[your-message]\r\n\r\n-- \r\nThis e-mail was sent from a contact form on MẪU GIAO DIỆN WEBVN027 (http://linhkien.maugiaodien.com)\nReply-To: hi@123web.vn\n\n\n\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nThe field is required.\nThe field is too long.\nThe field is too short.\nĐịnh dạng ngày tháng không hợp lệ.\nNgày này trước ngày sớm nhất được cho phép.\nNgày này quá ngày gần nhất được cho phép.\nTải file lên không thành công.\nBạn không được phép tải lên file theo định dạng này.\nFile kích thước quá lớn.\nTải file lên không thành công.\nĐịnh dạng số không hợp lệ.\nCon số nhỏ hơn số nhỏ nhất cho phép.\nCon số lớn hơn số lớn nhất cho phép.\nCâu trả lời chưa đúng.\nĐịa chỉ e-mail không hợp lệ.\nURL không hợp lệ.\nSố điện thoại không hợp lệ.', 'Contact form 1', '', 'publish', 'closed', 'closed', '', 'contact-form-1', '', '', '2020-05-01 23:56:10', '2020-05-01 16:56:10', '', 0, 'http://linhkien.maugiaodien.com/?post_type=wpcf7_contact_form&#038;p=5', 0, 'wpcf7_contact_form', '', 0),
(8, 3, '2018-08-29 12:18:21', '2018-08-29 12:18:21', '<!-- wp:flatsome/uxbuilder -->\n[gap class=\"gap-white\"]\n\n[section bg_color=\"rgb(243, 245, 247)\" padding=\"0px\"]\n\n[row col_bg=\"rgb(255, 255, 255)\"]\n\n[col span=\"3\" span__sm=\"12\" visibility=\"hide-for-small\"]\n\n[ux_sidebar id=\"widget-in-home\"]\n\n\n[/col]\n[col span=\"9\" span__sm=\"12\"]\n\n[ux_slider class=\"slider-home\"]\n\n[ux_image id=\"393\"]\n\n[ux_image id=\"157\" image_size=\"original\"]\n\n\n[/ux_slider]\n[gap height=\"15px\" class=\"gap-white\"]\n\n[row_inner label=\"Cảm biến\" col_bg=\"rgb(255, 255, 255)\"]\n\n[col_inner span__sm=\"12\"]\n\n[title text=\"Cảm biến\" link_text=\"Xem thêm\" link=\"/danh-muc/cam-bien/\" class=\"title_danh_muc_sp\"]\n\n[ux_products type=\"row\" cat=\"26\" orderby=\"date\"]\n\n\n[/col_inner]\n\n[/row_inner]\n[gap height=\"15px\" class=\"gap-white\"]\n\n[row_inner label=\"Linh kiện điện tử\" col_bg=\"rgb(255, 255, 255)\"]\n\n[col_inner span__sm=\"12\"]\n\n[title text=\"Linh kiện điện tử\" link_text=\"Xem thêm\" link=\"/danh-muc/linh-kien-dien-tu\" class=\"title_danh_muc_sp\"]\n\n[ux_products slider_nav_style=\"simple\" orderby=\"date\"]\n\n\n[/col_inner]\n\n[/row_inner]\n[gap height=\"15px\" class=\"gap-white\"]\n\n[row_inner label=\"Mạch điện\" col_bg=\"rgb(255, 255, 255)\"]\n\n[col_inner span__sm=\"12\"]\n\n[title text=\"Mạch điện\" link_text=\"Xem thêm\" link=\"/danh-muc/mach-dien/\" class=\"title_danh_muc_sp\"]\n\n[ux_products slider_nav_style=\"simple\" cat=\"15\" orderby=\"date\"]\n\n\n[/col_inner]\n\n[/row_inner]\n[gap height=\"15px\" class=\"gap-white\"]\n\n[row_inner label=\"Module\" col_bg=\"rgb(255, 255, 255)\"]\n\n[col_inner span__sm=\"12\"]\n\n[title text=\"Module\" link_text=\"Xem thêm\" link=\"/danh-muc/module/\" class=\"title_danh_muc_sp\"]\n\n[ux_products type=\"row\" cat=\"25\" orderby=\"date\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section label=\"cam kết\" bg_color=\"rgb(243, 245, 247)\"]\n\n[row style=\"collapse\" col_bg=\"rgb(255, 255, 255)\" v_align=\"equal\" padding=\"10px 0px 0px 0px\" class=\"ct-cam-ket product-row-1\"]\n\n[col span=\"3\" span__sm=\"6\" align=\"center\"]\n\n[featured_box img=\"194\" img_width=\"35\"]\n\n<p style=\"text-align: center;\"><strong>Lắp đặt chuyên nghiệp</strong><br /><span style=\"font-size: 75%;\">Đội ngũ lắp đặt, tư vấn kỹ thuật giàu kinh nghiệm</span></p>\n\n[/featured_box]\n\n[/col]\n[col span=\"3\" span__sm=\"6\" align=\"center\"]\n\n[featured_box img=\"196\" img_width=\"35\"]\n\n<p style=\"text-align: center;\"><strong>Giao nhận tiện lợi</strong><br /><span style=\"font-size: 75%;\">Giao nhận trong ngày nhanh chóng, an toàn</span></p>\n\n[/featured_box]\n\n[/col]\n[col span=\"3\" span__sm=\"6\" align=\"center\"]\n\n[featured_box img=\"195\" img_width=\"35\"]\n\n<p style=\"text-align: center;\"><strong>Thanh toán linh hoạt</strong><br /><span style=\"font-size: 75%;\">Phương thức thanh toán đa dạng, tiện lợi</span></p>\n\n[/featured_box]\n\n[/col]\n[col span=\"3\" span__sm=\"6\" align=\"center\"]\n\n[featured_box img=\"193\" img_width=\"35\"]\n\n<p style=\"text-align: center;\"><strong>Hậu mãi chu đáo</strong><br /><span style=\"font-size: 75%;\">Chăm sóc khách hàng tận tình</span></p>\n\n[/featured_box]\n\n[/col]\n\n[/row]\n\n[/section]\n\n<!-- /wp:flatsome/uxbuilder -->', 'Trang chủ', '', 'publish', 'closed', 'closed', '', 'trang-chu', '', '', '2025-02-10 03:05:40', '2025-02-09 20:05:40', '', 0, 'http://linhkien.maugiaodien.com/?page_id=8', 0, 'page', '', 0),
