(48, 3, '2018-08-29 20:03:25', '2018-08-29 13:03:25', 'Còi hú 12V công suất cao\r\n\r\n<strong>THÔNG SỐ KĨ THUẬT</strong>\r\n<ul>\r\n 	<li>Điện áp hoạt động: 5 ~ 12VDC</li>\r\n 	<li>Điện áp định mức : 12V</li>\r\n 	<li>Dòng điện tiêu thụ: 97mA</li>\r\n 	<li>Biên độ âm thanh: 110dB</li>\r\n 	<li>Tần số cộng hưởng: 2500Hz ± 500Hz</li>\r\n 	<li>Nhiệt độ hoạt động: -20 °C đến +70 °C</li>\r\n 	<li>Khối lượng: 50g.</li>\r\n</ul>', 'Còi hú 12V công suất cao', 'Còi hú 12V công suất cao', 'publish', 'closed', 'closed', '', 'coi-hu-12v-cong-suat-cao', '', '', '2018-08-29 20:03:25', '2018-08-29 13:03:25', '', 0, 'http://linhkien.maugiaodien.com/?post_type=product&#038;p=48', 0, 'product', '', 0),
