(52, 3, '2018-08-29 20:07:09', '2018-08-29 13:07:09', 'Module FET dùng mosfet IRF520 dùng để đóng ngắt các thiết bị công suất như motor, LED, quạt, laser…. Kích thước nhỏ, có đèn báo trạng thái hoạt động.\r\n\r\n<strong>THÔNG SỐ KĨ THUẬT</strong>\r\n<ul>\r\n 	<li>Điện áp giao tiếp: 3.3~5VDC</li>\r\n 	<li>Điện áp cấp cho tải: 0~24VDC</li>\r\n 	<li>Dòng tối đa: &lt;5A.</li>\r\n 	<li>Kích thước : 33.5 x 25.5 mm</li>\r\n 	<li>Trọng lượng : 10g</li>\r\n</ul>\r\n<strong>SƠ ĐỒ ĐẤU DÂY SỬ DỤNG ARDUINO</strong>\r\n\r\n<img class=\"aligncenter wp-image-54 size-full\" src=\"http://linhkien.maugiaodien.com/wp-content/uploads/2018/08/irf520use.jpg\" alt=\"\" width=\"800\" height=\"600\" />', 'Mạch Công Suất MOSFET IRF520', 'Module FET dùng mosfet IRF520 dùng để đóng ngắt các thiết bị công suất như motor, LED, quạt, laser…. Kích thước nhỏ, có...', 'publish', 'closed', 'closed', '', 'mach-cong-suat-mosfet-irf520', '', '', '2018-08-29 20:07:09', '2018-08-29 13:07:09', '', 0, 'http://linhkien.maugiaodien.com/?post_type=product&#038;p=52', 0, 'product', '', 0),
