(307, 3, '2019-09-09 10:20:12', '2019-09-09 03:20:12', '<strong>Mạch khuếch đại âm thanh bluetooth XY-P15</strong> 2x15W  là mạch khuếch đại tầm trung với công suất loa 15W tương đối dễ tìm và thích hợp cho việc nghe nhạc trong gia đình. Mạch sử dụng dải điện áp rộng nên thích hợp cho các loại nguồn từ 8-24V. Mạch có chất lượng gia công tốt, bluetooth nhạy và độ trễ cực thấp (hầu như không).\r\n<h3><strong>THÔNG SỐ KỸ THUẬT</strong></h3>\r\n<ul>\r\n 	<li>Mô hình: XY-P15W</li>\r\n 	<li>Điện áp làm việc: 8 ~ 24 VDC</li>\r\n 	<li>Phiên bản Bluetooth 5.0</li>\r\n 	<li>Khoảng cách truyền: 15 mét (không bị cản trở)</li>\r\n 	<li>Số lượng kênh: 2 kênh (âm thanh nổi)</li>\r\n 	<li>Công suất đầu ra (@ 1KHz)\r\n<ul>\r\n 	<li>2x16W  – 12V 4Ω</li>\r\n 	<li>2x10W  – 12V 8Ω</li>\r\n 	<li>2x15W  – 16V 8Ω</li>\r\n 	<li>2x20W – 20V 8Ω</li>\r\n 	<li>2x30W  24V 8Ohm (yêu cầu tản nhiệt)</li>\r\n</ul>\r\n</li>\r\n 	<li>Trở kháng loa\r\n<ul>\r\n 	<li>4 ohms (cung cấp điện 8 ~ 12V)</li>\r\n 	<li>8 ohms (cung cấp điện 8 ~ 24V)</li>\r\n 	<li>16 ohms (cung cấp điện 8 ~ 24V)</li>\r\n</ul>\r\n</li>\r\n 	<li>Cơ chế bảo vệ mô-đun\r\n<ul>\r\n 	<li>Bảo vệ điện đảo ngược</li>\r\n 	<li>Bảo vệ ngắn mạch</li>\r\n 	<li>Tự phục hồi quá nhiệt bảo vệ</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h3><strong>HÌNH MẠCH KHUẾCH ĐẠI ÂM THANH BLUETOOTH</strong></h3>\r\n<a class=\"photolightbox\" title=\"AUTO-DRAFT\" href=\"http://linhkien.maugiaodien.com/wp-content/uploads/2019/09/auto-draft-307-2811.jpg\"><img class=\"aligncenter\" src=\"http://linhkien.maugiaodien.com/wp-content/uploads/2019/09/auto-draft-307-2811.jpg\" alt=\"AUTO-DRAFT\" /></a>\r\n\r\n<a class=\"photolightbox\" title=\"AUTO-DRAFT\" href=\"http://linhkien.maugiaodien.com/wp-content/uploads/2019/09/auto-draft-307-7982.jpg\"><img class=\"aligncenter\" src=\"http://linhkien.maugiaodien.com/wp-content/uploads/2019/09/auto-draft-307-7982.jpg\" alt=\"AUTO-DRAFT\" /></a>', 'Mạch khuếch đại âm thanh bluetooth XY-P15 2x15W', '<strong>Mạch khuếch đại âm thanh bluetooth XY-P15</strong> 2x15W  là mạch khuếch đại tầm trung với công suất loa 15W tương đối dễ tìm và thích hợp cho việc nghe nhạc trong gia đình.', 'publish', 'closed', 'closed', '', 'mach-khuech-dai-am-thanh-bluetooth-xy-p15-2x15w', '', '', '2019-09-09 10:20:12', '2019-09-09 03:20:12', '', 0, 'http://linhkien.maugiaodien.com/?post_type=product&#038;p=307', 0, 'product', '', 0),
